/**
 * Breadcrumb 컴포넌트
 * 현재 페이지 항목 하이라이트 처리
 */
export function initBreadcrumb(root = document) {
  const breadcrumbs = root.querySelectorAll('[data-lg-breadcrumb]');

  breadcrumbs.forEach((breadcrumb) => {
    const currentPath = breadcrumb.dataset.lgBreadcrumbCurrent;
    if (!currentPath) return;

    const items = breadcrumb.querySelectorAll('.lg-breadcrumb__item');
    items.forEach((item) => {
      const link = item.querySelector('.lg-breadcrumb__link');
      if (link && link.getAttribute('href') === currentPath) {
        item.classList.add('lg-breadcrumb__item--current');
        link.removeAttribute('href');
        link.setAttribute('aria-current', 'page');
      }
    });
  });
}

export default initBreadcrumb;
